#!/usr/bin/env python3
"""sen0414_lineage_exam_revfix v1_0_0 - ONE new register file: registers the repair story ST4_RevFix (corrections version of the printed midterm: sheet wording and row F line, 10 pt labels, slack of the last question page of at least 40 pt, cover overshoot, sheet footer box and orphan line) with its objective, build and verification tasks, brief r18, and re-ranks the open stories. Usage: python3 sen0414_lineage_exam_revfix_v1_0_0.py"""
__version__ = "1.0.0"
import hashlib, os, re, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import sen0414_lineage_standard_v1_2_0 as W
def blk(t, name):
    i = t.index("\nex:%s a backlog:" % name) + 1; j = t.find("\nex:", i + 1)
    return i, (len(t) if j < 0 else j)
src = W.newest(); t = open(src, encoding="utf-8").read(); now = W.now(); nowZ = now + "Z"; add = []
BF = "08-tooling/briefs/exam/r18/BRIEF_TK4_RevFix_Build.md"; SHA = hashlib.sha256(open(os.path.join(W.REPO, BF), "rb").read()).hexdigest()
OWN = ("OWNER DECISION of 2026-11-02 16:50 Istanbul (13:50Z), relayed by the coordinator and recorded as relayed: print the committed PDF of the first version now; the small flaws go into a later version: the sheet header 'form code 10100' that students never fill, the row F line 'Give the code of one bank word', the 9.5 pt answer labels, the 0.55 pt cover overshoot, the sheet footer box and the orphan 'it.' on sheet page 1. COORDINATOR INSTRUCTION of the same time: register them as a repair item with a brief for a corrections version (sheet wording and row F line, 10 pt labels, a slack of at least 40 pt on the last question page by moving sub-question 4f, the cover overshoot). Found by part 4 of TK4_Rev_Papers (measure log papers_r15/exam_papers_measure_v1_0_0_log.txt, CME commit 2a62393) and confirmed by the lineage agent's own control (kept logs 08-tooling/control-exam-logs/control_revmeasure_run1.log and control_revpapers_run3.log). The first version stays valid and printed; nothing is withdrawn.")
ST = ("ST4_RevFix", "Corrections version of the printed midterm: sheet wording, 10 pt labels, last-page slack, cover and sheet edges")
TASKS = [("TK4_RevFix_Build", "Build", "Corrections version: sheet wording v1.1.0 and sheet v2.2.0, 10 pt labels, 4f moved for a slack of 40 pt, cover overshoot, sheet footer and orphan line", "Deliverable and checks: see the brief %s (generated by the lineage agent, r18; SHA-256 %s); executor session SEN0414-EX-rev-fix1; new versioned files in /home/claude/CME/exams/SEN0414, nothing in the public repository, the first version's files and the build are not edited. Estimated 2.0 hours (an estimate, G120). " % (BF, SHA) + OWN, "TK4_Rev_Papers_Verify"),
         ("TK4_RevFix_Verify", "Verify", "Verify: corrections version of the printed midterm", "Control by the lineage agent on its own re-runs of the checks named in the brief %s: the measure of the paper and sheet (no FAIL, no RISK; Word stays NOT_MEASURED), the build unchanged byte for byte or E01 to E34 and the key letters re-read, the marking tool 110 and 0 on the real key, the reader on the fixture sheets, no exam file in the public repository. An incomplete run is a result, not a pass. Estimated 0.5 hours (an estimate, G120)." % BF, "TK4_RevFix_Build")]
def refine(k, tag="6a"):
    add.append('ex:Refine%s_%s a backlog:RefinementEvent ; rdfs:label "Refinement that made %s ready"@en ;\n    backlog:refines ex:%s ; backlog:addressesConcern backlog:Concern_Data ; backlog:refinedAt "%s"^^xsd:dateTime ;\n    backlog:refinedBy backlog:Builder ; backlog:groomsForIteration ex:Iter_Ex3 ; backlog:hasWorkKind backlog:WorkKind_Preparation ;\n    backlog:hasRefinementOutcome "Refined from the Owner decision and the coordinator instruction of 2026-11-02 (16:50 Istanbul): deliverable, check, brief and estimate are written in the item." .\n' % (tag, k, k, k, now))
    add.append('ex:RC%s_%s a backlog:ReadinessCheck ; rdfs:label "Readiness check of %s"@en ; backlog:checksReadinessOf ex:%s ; backlog:readinessCheckedAt "%s"^^xsd:dateTime ;\n    backlog:hasReadinessCriterion ex:RK%s_%s_1, ex:RK%s_%s_2, ex:RK%s_%s_3 .\n' % (tag, k, k, k, now, tag, k, tag, k, tag, k))
    for kx, tx in ((1, "The deliverable, its place and its check are written in the item or its brief."), (2, "Every dependency of the item is Done or a task of the same story that precedes it."), (3, "The statements that bound the item are recorded on the story.")):
        add.append('ex:RK%s_%s_%d a backlog:ReadinessCriterion ; rdfs:label %s@en ; backlog:criterionMet true .\n' % (tag, k, kx, W.lit(tx)))
    add.append('ex:Mv%s_%s a backlog:TransitionEvent ; rdfs:label "%s moved to Ready"@en ; backlog:transitionedItem ex:%s ;\n    backlog:viaTransition backlog:T_Refine ; backlog:transitionedAt "%sZ"^^xsd:dateTime ; backlog:transitionedBy backlog:Builder ;\n    backlog:hasTransitionNote "Refined (ex:Refine%s_%s) and ready after the readiness check ex:RC%s_%s; no executor has started." .\n' % (tag, k, k, k, now, tag, k, tag, k))
sid = ST[0]
add.append('\nex:%s a backlog:Story ; rdfs:label %s@en ; backlog:hasIdentifier "%s" ; backlog:hasTitle %s ;\n    backlog:belongsToLineage ex:Lineage4 ; backlog:memberOfContainer ex:Iter_Ex3 ; backlog:responsible ex:Executor_ClaudeCodeSession ; backlog:admittedByOutput ex:Out4_Backlog ;\n    backlog:hasInvestmentCategory backlog:Cat_Compliance ;\n    backlog:asRole "SEN0414 instructor" ; backlog:wantsCapability "a corrections version of the printed midterm without the known print flaws" ; backlog:soThat "the next printing of the midterm and the make-up has no wording that confuses students and no page that a different word processor can push to an extra page" ;\n    backlog:satisfiesDeliverable ex:Del4_Papers ; backlog:pursuesObjective ex:Obj7_PrintFlaws ; backlog:hasAcceptanceCriterion ex:AC4_Controlled ;\n    backlog:coversEntity ex:DE4_ExamPaper ; backlog:coversStage backlog:Stage_Creation ;\n    backlog:effectiveDefinitionOfDone ex:DoD ; backlog:hasApplicableConcern backlog:Concern_Data ;\n    backlog:decomposesInto ex:TK4_RevFix_Build, ex:TK4_RevFix_Verify ;\n    backlog:hasState backlog:Ready ; backlog:hasPriorityScore ex:Score6a_%s ;\n    backlog:hasAuditNote %s .\n' % (sid, W.lit(ST[1]), sid, W.lit(ST[1]), sid, W.lit(OWN)))
add.append('ex:Score6a_%s a backlog:PriorityScore ; backlog:scoredByMethod backlog:Method_WSJF ;\n    backlog:hasScoreValue "7.20"^^xsd:decimal ; backlog:scoredAt "%sZ"^^xsd:dateTime ; backlog:isAveragedFromMembers false ;\n    backlog:hasScoreRationale "WSJF = (business value 8 + time criticality 5 + risk reduction 5) / job size 2.5 h = 7.20. First scoring %s UTC; the first version is printed and fit to use, so the time criticality is low; the risk reduction is the sixth page in Word and the confusing form code." .\n' % (sid, now, now))
refine(sid)
for k, typ, title, note, dep in TASKS:
    add.append('\nex:%s a backlog:ExecutionTask ; rdfs:label %s@en ; backlog:hasIdentifier "%s" ; backlog:hasTitle %s ;\n    backlog:belongsToLineage ex:Lineage4 ; backlog:memberOfContainer ex:Iter_Ex3 ; backlog:admittedByOutput ex:Out4_Backlog ; backlog:responsible ex:Executor_ClaudeCodeSession ;\n    backlog:hasInvestmentCategory backlog:Cat_Compliance ; backlog:hasTaskType backlog:TaskType_%s ; backlog:effectiveDefinitionOfDone ex:DoD ; backlog:hasState backlog:Ready ;\n    backlog:dependsOn ex:%s ;\n    backlog:notYetScoreable true ; backlog:hasScoreabilityReason "Ranked by its story\'s state; scoring both would double-count." ;\n    backlog:hasAuditNote %s .\n' % (k, W.lit(title), k, W.lit(title), typ, dep, W.lit(note)))
    refine(k)
add.append('ex:Plan6a_%s a backlog:PlanningEvent ; rdfs:label "Planning of %s into box 3"@en ; backlog:belongsToLineage ex:Lineage4 ;\n    backlog:plannedAt "%s"^^xsd:dateTime ; backlog:plannedBy backlog:Builder ; backlog:plannedInto ex:Iter_Ex3 ;\n    backlog:plansItem ex:%s ; backlog:producesTask ex:TK4_RevFix_Build, ex:TK4_RevFix_Verify ;\n    backlog:refinementProduces ex:Spec4, ex:Scen4_Sound, ex:Scen4_Refused .\n' % (sid, sid, now, sid))
add.append("ex:Iter_Ex3 backlog:hasMember ex:%s, ex:TK4_RevFix_Build, ex:TK4_RevFix_Verify .\nex:EP4_Engine backlog:decomposesInto ex:%s .\n" % (sid, sid))
add.append('ex:Met7_PrintFlaws a backlog:Metric ; rdfs:label "known print flaws of the first printed midterm (paper and answer sheet)"@en ; backlog:belongsToLineage ex:Lineage4 .\nex:Obj7_PrintFlaws a backlog:Objective ; rdfs:label "Known print flaws of the printed midterm: from 7 to 0"@en ; backlog:belongsToLineage ex:Lineage4 ;\n    backlog:contributesToGoal ex:G4_PapersExist ; backlog:fillsScope ex:Scope4 ; backlog:hasSuccessMetric ex:Met7_PrintFlaws ;\n    backlog:hasMeasurementKind backlog:Meas_Counted ;\n    backlog:hasMeasurementQuery "Counted from the measure tool run on the corrections version after the controller has re-run it: the misleading header, the row F line, labels under 10 pt, the cover overshoot above 0.1 pt, the sheet footer box, the orphan line, and a last-page slack under 40 pt (seven in the first version)." ;\n    backlog:hasBaselineValue "7"^^xsd:decimal ; backlog:hasTargetValue "0"^^xsd:decimal ; backlog:hasTargetDirection backlog:Dir_Decrease ;\n    backlog:hasCheckpoint ex:CP7_Obj7_PrintFlaws ;\n    backlog:hasIntentOrigin backlog:IOrigin_Derived ; backlog:decidedBy backlog:Owner ; backlog:producedByStage ex:Out4_Objective .\nex:CP7_Obj7_PrintFlaws a backlog:ObjectiveCheckpoint ; rdfs:label "Reading after the controller has re-run the measure tool on the corrections version"@en ;\n    backlog:checkpointCondition "Taken after the controller\'s own re-run of the measure tool." ; backlog:expectedValue "0"^^xsd:decimal .\nex:Obj7_PrintFlaws backlog:metricMovableBy ex:%s .\n' % sid)
add.append('ex:Obs70a_Obj7_PrintFlaws a backlog:MetricObservation ; rdfs:label "Reading when the repair item was registered"@en ;\n    backlog:observesMetric ex:Met7_PrintFlaws ; backlog:observationFor ex:Obj7_PrintFlaws ; backlog:hasObservedValue "7"^^xsd:decimal ; backlog:observedAt "%sZ"^^xsd:dateTime ;\n    backlog:hasObservationMethod "Counted by part 4 of TK4_Rev_Papers (measure log, CME commit 2a62393) and checked by the lineage agent (control_revmeasure_run1.log): 7 known flaws of the first version." .\n' % now)
done = ['ST4_RevFix', 'TK4_RevFix_Build', 'TK4_RevFix_Verify']
for s2 in sorted(set(re.findall(r"\nex:(ST\w*?_\w+) a backlog:Story", t))):
    i, j = blk(t, s2); b = t[i:j]
    m = re.search(r"backlog:hasPriorityScore ex:Score(\d+[a-z]?)_%s\b" % s2, b)
    if not m or "backlog:hasState backlog:Done" in b or "backlog:hasState backlog:Cancelled" in b: continue
    kk = m.group(1)
    if ("\nex:Score%s_%s a" % (kk, s2)) not in t: continue
    k0 = t.index("\nex:Score%s_%s a" % (kk, s2)) + 1; r0 = t[k0:t.find("\nex:", k0 + 1)]
    q = re.search(r"business value (\d+) \+ time criticality (\d+) \+ risk reduction (\d+)\) / job size ([\d.]+) h", r0)
    if not q: continue
    nk = (kk[:-1] + chr(ord(kk[-1]) + 1)) if kk[-1].isalpha() else str(int(kk) + 1); nid = "Score%s_%s" % (nk, s2)
    if ("ex:" + nid + " a ") in t: continue
    bv, tc, rrr, size_ = int(q.group(1)), int(q.group(2)), int(q.group(3)), float(q.group(4)); val = (bv + tc + rrr) / size_
    t = t[:i] + b.replace(m.group(0), "backlog:hasPriorityScore ex:" + nid, 1) + t[j:]
    add.append('ex:%s a backlog:PriorityScore ; backlog:scoredByMethod backlog:Method_WSJF ;\n    backlog:hasScoreValue "%.2f"^^xsd:decimal ; backlog:scoredAt "%sZ"^^xsd:dateTime ; backlog:isAveragedFromMembers false ;\n    backlog:hasScoreRationale %s .\n' % (nid, val, now, W.lit("WSJF = (business value %d + time criticality %d + risk reduction %d) / job size %.1f h = %.2f. RE-RUN on %s UTC after the repair story entered (%s): a repair re-ranks the open items. Inputs unchanged." % (bv, tc, rrr, size_, val, now, ", ".join(done)))))
add.append("ex:Lineage4 backlog:hasAuditNote %s .\n" % W.lit("RANKING %s UTC after the repair story ST4_RevFix entered (a repair re-ranks the open items): its WSJF is 7.20 (job size 2.5 h); it is not urgent and waits behind the urgent items; the open stories were scored again on their unchanged inputs." % now))
out = W.write_new(src, t + "\n" + "".join(add), "Exam: repair story ST4_RevFix (corrections version of the printed midterm) registered Ready with brief r18.")
print(os.path.basename(out))
